/* MEMPHIS_DESIGN_START */
function memphisGlyph(a){return({gpt:'<path d="M20 11l7.8 4.5v9L20 29l-7.8-4.5v-9z" fill="none" stroke="#fff" stroke-width="3"/>',claude:'<path d="M20 10v20M10 20h20M13 13l14 14M27 13L13 27" stroke="#fff" stroke-width="3" stroke-linecap="round"/>',gemini:'<path d="M20 9q2 9 11 11q-9 2-11 11q-2-9-11-11q9-2 11-11z" fill="#fff"/>',deepseek:'<path d="M9 22q5.5-8 11 0t11 0" fill="none" stroke="#fff" stroke-width="3.2" stroke-linecap="round"/>',qwen:'<rect x="12" y="12" width="16" height="16" rx="3" fill="none" stroke="#fff" stroke-width="3.2"/>',grok:'<path d="M14 28L26 12" stroke="#fff" stroke-width="3.6" stroke-linecap="round"/>'})[a]||'<circle cx="20" cy="20" r="5" fill="#fff"/>'}
function memphisAvatar(a,sz=40,coordinator=false){const m=(typeof MODELS!=="undefined"&&MODELS[a])||null,c=m&&/^#[0-9a-f]{3,8}$/i.test(m[1])?m[1]:"#8792A2",n=m?m[0]:"未知模型",s=+sz||40,shape=coordinator?'<rect x="2" y="2" width="36" height="36" rx="9"':'<circle cx="20" cy="20" r="18"';return`<svg width="${s}" height="${s}" viewBox="0 0 40 40" role="img" aria-label="${esc(n)}${coordinator?" · 统筹":""}">${shape} fill="${c}" stroke="#1B2230" stroke-width="2.5"/>${memphisGlyph(m?a:"")}</svg>`}
function memphisStKey(st){return String(st||"idle").replace(/[^a-z]/gi,"")}
function memphisNode(p,m,x,y,sz,lead){const t=(typeof ST!=="undefined"&&ST[m.st])||"闲";return`<div class="pc" data-ag="${p.id}|${m.id}" style="left:${x}px;top:${y}px" title="${esc(m.name)} · ${esc(t)}"><span class="m-av">${piece(m.agent,sz,lead)}<span class="bb" data-st="${memphisStKey(m.st)}" role="img" aria-label="状态 ${esc(t)}">${esc(t)}</span></span><span class="nm">${esc(m.name)}</span></div>`}
function memphisProject(p){const s=p.space,r=s.r,ms=p.members||[],n=ms.length,c=p.ui.color,hot=typeof linkFrom!=="undefined"&&linkFrom===p.id,sel=state.sel===p.id,cy=r*1.08,mr=r*.6,big=Math.round(Math.min(52,Math.max(36,r*.3))),sm=Math.round(big*.74);const sum=String(p.summary||"");const inbox=state.inbox.some(i=>i.pid===p.id&&!i.done);
return`<div class="ring${sel?" sel":""}${hot?" hot":""}" data-pid="${p.id}" style="left:${s.x-r}px;top:${s.y-r}px;width:${2*r}px;height:${2*r}px;--c:${c}"><span class="rt" data-drag="p" title="${esc(p.name)}">${esc(p.name)}</span>${sum?`<span class="m-sum" title="${esc(sum)}">${esc(sum)}</span>`:""}${memphisNode(p,p.coordinator,r,cy,big,true)}${ms.map((m,i)=>{const t=Math.PI*.15+i*Math.PI*1.7/Math.max(n,1)+(n===1?Math.PI*.55:0);return memphisNode(p,m,r+Math.cos(t)*mr,cy+Math.sin(t)*mr*.62,sm,false)}).join("")}${inbox?`<span class="m-inbox" style="--c:${c}">${icon("inbox",13)}新收件</span>`:""}</div>`}
function memphisGroup(g,x,y){const c=g.coordinator,t=(typeof ST!=="undefined"&&ST[c.st])||"闲";return`<button class="gc" data-grp="${g.id}" style="left:${x}px;top:${y}px" aria-label="跨项目统筹 ${esc(c.name)} · ${esc(t)}">${piece(c.agent,32,true)}<span><b>${esc(c.name)}</b><small>${c.name==="跨项目统筹"?esc(t):"跨项目统筹 · "+esc(t)}</small></span></button>`}
function memphisChrome(){const gb=document.getElementById("gb");if(gb){[["[data-mc-open]","network","连接"],["[data-util=auth]","settings","授权"],["[data-util=prompt]","sparkles","Prompt"],["[data-a=guide]","help","讲解员"]].forEach(([q,i,t])=>{gb.querySelectorAll(q).forEach((b,k)=>{if(k>0){b.hidden=true;return}const html=icon(i,16)+`<span class="memphis-label">${t}</span>`;if(b.innerHTML!==html){b.innerHTML=html;b.dataset.mm="1"}b.setAttribute("aria-label",t);b.title=t})})}
document.querySelectorAll("#shelf .pc[data-model]").forEach(b=>{const m=MODELS[b.dataset.model];if(m&&!b.querySelector(".nm"))b.insertAdjacentHTML("beforeend",`<span class="nm">${esc(m[0])}</span>`)});
document.querySelectorAll("#tools button").forEach(b=>{if(b.querySelector(".memphis-label"))return;const t=(b.textContent||"").trim(),tt=({undo:"撤销",redo:"重做"})[b.dataset.act]||b.title||t;[...b.childNodes].forEach(n=>{if(n.nodeType===3&&n.textContent.trim())n.remove()});if(t)b.insertAdjacentHTML("beforeend",`<span class="memphis-label">${esc(t)}</span>`);if(tt){b.setAttribute("aria-label",tt);b.title=tt}})}
piece=memphisAvatar;
const memphisRenderTop=renderTop;renderTop=function(){memphisRenderTop();memphisChrome()};
/* MEMPHIS_DESIGN_END */
